import { NextRequest, NextResponse } from 'next/server';

export function middleware(request: NextRequest) {
  const { method, url } = request;
  const { pathname } = request.nextUrl;

  console.log(`[${new Date().toISOString()}] ${method} ${pathname}`);

  return NextResponse.next();
}

events.content:
This creates a `middleware.ts` at the project root that logs every request to the console. For each incoming request, it prints a line like:

```
[2026-02-18T12:34:56.789Z] GET /about
```

The middleware runs on all routes by default. If you ever need to exclude certain paths (e.g., static assets), you can add a `config` export with a `matcher`:

```ts
export const config = {
  matcher: '/((?!_next/static|_next/image|favicon.ico).*)',
};
```

